def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    first = True
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue
        # Determine sign
        if first:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '-' if coeff < 0 else '+'
        abs_coeff = abs(coeff)
        # Determine coefficient string
        if degree == 0:
            coeff_str = str(abs_coeff)
        else:
            coeff_str = '' if abs_coeff == 1 else str(abs_coeff)
        # Determine variable part
        if degree == 0:
            var_str = ''
        elif degree == 1:
            var_str = 'x'
        else:
            var_str = f'x^{degree}'
        terms.append(f'{sign}{coeff_str}{var_str}')
        first = False
    return ''.join(terms) if terms else '0'

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and uses this
    mapping to decode a given encrypted message. If a contradiction is found during mapping
    construction, or not all letters are represented in the mapping, the function returns "Failed".

    Args:
    encoded (str): A string representing the encoded information.
    original (str): A string representing the original information corresponding to the encoded string.
    message (str): A string representing the encrypted message to be decoded.

    Returns:
    str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping:
            if mapping[e] != o:
                return "Failed"
        else:
            mapping[e] = o

    # A complete cipher must map all 26 uppercase letters
    if len(mapping) < 26:
        return "Failed"

    decoded_chars = []
    for ch in message:
        if ch not in mapping:
            return "Failed"
        decoded_chars.append(mapping[ch])

    return "".join(decoded_chars)

def preorder_traversal(inorder: str, postorder: str) -> str:
    """
    Reconstructs the binary tree from its inorder and postorder traversals
    and returns the preorder traversal as a string.
    """
    def helper(in_l: str, post_l: str) -> str:
        if not in_l:
            return ""
        if len(in_l) == 1:
            return in_l
        root = post_l[-1]
        idx = in_l.index(root)
        left_in = in_l[:idx]
        right_in = in_l[idx + 1 :]
        left_post = post_l[: len(left_in)]
        right_post = post_l[len(left_in) : -1]
        return root + helper(left_in, left_post) + helper(right_in, right_post)

    return helper(inorder, postorder)

